    op.add_column('gmp_record', sa.Column('GMP_REFERENCE_NO', sa.String(length=50), nullable=True, comment='Reference Number — {DTN}-{sequence}, unique per issuance record'))
    op.drop_index(op.f('ix_gmp_record_GMP_DTN'), table_name='gmp_record')
