    for gmp_id, dtn in rows:
        seq_by_dtn[dtn] = seq_by_dtn.get(dtn, 0) + 1
        ref_no = f"{dtn}-{seq_by_dtn[dtn]:02d}"
        conn.execute(
            sa.text("UPDATE gmp_record SET GMP_REFERENCE_NO = :ref WHERE GMP_ID = :id"),
            {"ref": ref_no, "id": gmp_id},
        )


